      'answer': 'باستخدام مسدس أو مثقاب يدوي تكتيكي خاص (EZ-IO) لغرس إبرة الإي أو الفولاذية في تجويف نخاع عظم القص أو رأس عظم الفسائل بالركبة كمجرى تسريب سريع لا ينطوي.'
