      'answer': 'لأن تركيبته الكيميائية تشابه إلى حد كبير السائل الفيزيولوجي البشري ويحتوي على اللاكتات التي يحولها الكبد لبيكربونات لمعادلة حموضة الصدمة بالجسم.'
