      'answer': 'هو تجميع الدم النظيف المتراكم بتجويف صدر أو بطن المصاب أثناء الجراحة الاستكشافية وتصفيته عبر شاش معقم لتسريبه وإرجاعه فوراً لذات المريض لسرعة التعويض.'
    },
