      'answer': 'الكسر الشرياني المعيق، فقد الأوردة المحيطية التام بالكامل، وتعذر التركيب النخاعي العظمي مع ضرورة قياس الضغط الوريدي المركزي وتوجيه الفازوبريسين.'
    },
    {
      'question': 'ما هي أعراض الحساسية الدموية البسيطة وكيف تعالج أثناء تسريب دم طازج حار لمصنع؟',
