      'answer': 'يتم بتدفق حاد ذي اتجاه واحد غير متقاطع (One-way triage flow): مدخل خارجي للفرز، يليه مناطق المعالجة الحمراء ثم الصفراء، ثم منطقة الانتظار والإخلاء، للتخلص من عنق الزجاجة وصيانة الزمن.'
    },
