      'answer': 'استقرار السيطرة على مجرى الهواء الرئوي بالكامل، إمكانيات بزل الصدر الحيوية منجزة، النبض والدوران مستقس بضغط مقبول، تدوين تقارير التسليم الطبي MIST بدقة، وحزم المصاب لمنع تجلط الصقيع.'
