      'answer': 'هي القدرة على صون حياة وعناية المريض تحت الحصار من غياب الطيران النقال، لفترات تبدأ من 12 ساعة وتمتد لـ 72 ساعة عبر رصد المحاليل ومنع تدمير الصقيع والتقنيات المحمولة.'
