      'answer': 'التريداق النوعي هو عقار النالكسون (Naloxone) بجرعة 0.4 ملغ تحقن وريدياً أو عضلياً بالتكرار المناسب حتى ترجع بساطة وعي وتنفس المصاب بالكامل.'
