      'answer': 'يحقن موضعياً بتركيز 1% أو 2% حول موضع التدخل لغلق مستقبلات الصوديوم العصبية مسبباً تنويماً وخلق ارتياح تام للجلد المصاب قبل الخياطة أو الإجراء.'
