      'answer': 'يوسع الشرايين الإكليلية المغذية للقلب والوريد العام مما يقلل العائد الدموي والمجهود القلبي، وتكرر الحبوب كل 5 دقائق لثلاث مرات مع مراقبة صارمة للضغط.'
