      'answer': 'الجرعة هي 1 أو 2 جرام وريدياً كل 8 ساعات، لغمر خلايا الجسم بمكافحة البكتيريا إيجابية ومعدمة الغرام، وصيانة مفاصل الجرحى من التآكل البكتيري.'
