      'answer': 'استخدام شرائح الفحص الفورية السريعة (EldonCard) عبر تلطيخ قطرات دم الجريح بمفاصل الأجسام المضادة المجففة على الورقة وقراءة النتائج بالتروي غضون دقيقة.'
