      'answer': 'تدل على حدوث تفاعل دم تحللي مناعي شديد (Acute Hemolytic Transfusion Reaction) نتيجة فصيلة خاطئة، ويجب المسارعة بوقف تسريب كيس الدم فوراً وإعطاء ملح ومدر بوول.'
