      'answer': 'هو إبقاء الضغط الدموي الانقباضي بحدود 80-90 مم زئبق (نبض كعبري بالكاد محسوس وخلف وعي بوابي مستقر) للحفاظ على التروية الدماغية دون فرقعة الجلطات الطبيعية بمناطق النزف.'
    },
    {
