      'answer': 'لأن تذبذب توازن ذرات الكالسيوم بالدم جراء حمض السترات يعوق تقلص ومرونة عضلة القلب وشرايين الأطراف ويهدد باحتشاء وموت خلايا عضلة القلب ببطء.'
    },
    {
