      'answer': 'سحب الإبرة النخاعية فور تأمين مسار وريدي مناسب خلال 24 ساعة، غسيل موضعي معقم لثقب العظم، والالتزام بجرعات الدواء الوقائي من المضاد الحيوي سيفازولين.'
    },
