      'answer': 'الغليان المستمر لدقيقتين، استخدام أقراص الكلور (هيبوكلوريت الكالسيوم) بنسبة محسوبة (حوالي 0.5 ملغ/لتر ككلور حر متبقٍ)، أو استخدام مرشحات الفخار الترشيحية الكيميائية المحمولة.'
