      'answer': 'توضع بعيدة تماماً عن مجاري مياه السيول وأسفل مصادر الآبار بمسافة لا تقل عن 30 متراً، وتغطى بانتظام بالتراب والجير الحي لمنع توالد الذباب والحشرات الوبائية.'
    },
