      'answer': 'العزل الكلي الحاسم لجميع ذوي الأعراض بكهف معزول، وتوزيع الدوكسيسيكلين أو الإريثرومايسين كعلاج وقائي كيميائي وقائي لجميع المخالطين، وفحص كروت التطعيم.'
    },
    {
