    },
    {
      'question': 'ما هي درجة الحرارة المثالية لحفظ الوجبات واللحوم المجمدة بمستودعات الإمداد اللائحة للطب الوقائي؟',
      'answer': 'اللحوم تحفظ مجمدة تحت -18 درجة مئوية، ومحاور المعلبات في أماكن جافة مهواة حرارتها لا تفوق 25 درجة مئوية لمنع تحلل ونخر المنتجات.'
    },
    {
      'question': 'كيف يتم تطهير معسكر أو حظيرة طبية عانت من تفشي وباء الجرب (Scabies)؟',
