    },
    {
      'question': 'كيف يتم تحديد مخاطر التعرض للأسبستوس والجسيمات الصدرية المسرطنة بمواقع الهدم والانفجار التكتيكي؟',
      'answer': 'بتوجيه حاسم لارتداء كشافات التنفس ذات المرشح الهيبا (HEPA Masks)، وتجنب العيش بمغارات أو غرف مهدمة تحوي عوازل أسبستوسية غبارية.'
    },
    {
      'question': 'ما وظيفة لقاح داء الكلب (Anti-Rabies) وجرعاته الوقائية للجندي بعد عضة حيوان بساحة القباء؟',
      'answer': 'الغسيل الفوري الوفير للجرح بالصابون والماء الجاري، وحقن الجلوبيولين المناعي لداء الكلب حول بؤرة الجرح، تليها 4 جرعات من اللقاح بالأيام المحددة 0-3-7-14.'
    },
    {
      'question': 'كيف تؤمن النفايات الطبية الحادة (الحقن المبذولة والإبر الجراحية السامة) بمحيط الكادر؟',
      'answer': 'توضع في حاويات فولاذية أو بلاستيكية سميكة مانعة للاختراق (Sharps Containers)، وتدفن في حفر جافة عميقة بعمق مترين مع صب الخرسانة عليها وقائياً.'
    },
    {
      'question': 'ما هي الأضرار السريرية الناتجة عن تلوث المياه بعنصر الرصاص الكيميائي بمقذوفات الرصاص؟',
      'answer': 'يسبب تدميراً عصبياً متتابعاً وخلايا فقر دم شديد، تلف النفرونات الكلوية، والإجهاضات المتلاحقة للحوامل بمواضع العيش المجاور للجبهة.'
    },
    {
      'question': 'كيف يتم العناية بنظافة الخنادق والأنفاق الرطبة وقائياً لتفادي فطر القدم الرياضية السام؟',
      'answer': 'حث الجنود على تبديل الجوارب الرطبة يومياً وتجفيف الأقدام بالهواء ولبس أحذية عسكرية متسعة، واستخدام مساحيق ومطهرات التلك المضادة للفطريات.'
    },
    {
      'question': 'ما هو دور لقاح وباء التيتانوس (الكزاز - Tetanus Vaccine) وجرعاته التنشيطية بمسار الكلية؟',
      'answer': 'يعطى لقاح التيتانوس كوقاية أولية بـ 3 جرعات، وتوفر جرعة منشطة كل 5 إلى 10 سنوات مناعة هائلة ضد ذيفان بكتيريا الكلوستريديوم الشائعة بتربة الدفاع.'
    },
    {
      'question': 'كيف يتم تأهيل المطابخ الجبهية وتدابير منع انتقال الميكروبات المعوية (Shigella / E.coli)؟',
      'answer': 'بعزل الطباخين الذين تظهر عليهم أعراض معوية، تطهير السكاكين والأسطح بانتظام بماء كلور، وتغطية مخازن الطعام لعدم تواصل الذباب والملوثات.'
    },
    {
      'question': 'ما هي الفحوصات المعملية الوقائية لتأكيد سلامة الأبقار والمواشي قبل ذبحها لقوات الجبهة؟',
      'answer': 'الفحص البيطري الظاهري للتأكد من خلوها من الحمى القلاعية، حمى الوادي المتصدع، والسل، ومراقبة تماسك الكبد والأحشاء واللحوم بعد الذبح.'
    },
    {
      'question': 'كيف يتم مكافحة ذباب الرمل ومواجهة وباء اللشمانيا الجلدية (Leishmaniasis) بالمناطق الموبوءة بالصقيع؟',
      'answer': 'برش الجدران الداخلية للمغارات بمبيدات ذات مفعول باقٍ ومستمر، استخدام الناموسيات ذات الفتحات الدقيقة المشبعة بالمبيد، ودهان الجلد لمنع اللدغات.'
    },
    {
      'question': 'ما هي المعايير الوقائية لصحة المياه الجوفية ومنع تسرب مياه الصرف الصحي للآبار الاستهلاكية؟',
      'answer': 'أن تكون حواجز امتصاص الصرف الصحي عازلة للترسب وعميقة ومبنية بكتل أسمنتية صماء، وبمسافة أمان أفقية وعتبات مرتفعة لمنع السيول المباشرة.'
    },
    {
      'question': 'كيف تسهم عملية عزل النفايات البيولوجية للجرحى (الشاش المشبع بالدم والأنسجة البترية) في الحفاظ على صحة المعسكر؟',
      'answer': 'بحرقها فورياً في محارق صخرية مخصصة بارتفاع وتوجيه آمن لأبخرتها، لقتل الجراثيم اللاهوائية والفيروسات ومنع استيطان الكلاب والحيوانات البرية لها.'
    },

    // === Field Clinic Administration, Triage (MASCAL, START) & MEDEVAC (151-170) ===
    {
      'question': 'ما هو نظام الفرز البسيط والنقل السريع (START Protocol) في إدارة الإصابات الجماعية (MASCAL)؟',
      'answer': 'هو بروتوكول لفرز المصابين سريعاً خلال 60 ثانية بناءً على 3 معايير: التنفس، الدوران، والوعي (RPM)، وتصنيفهم باستخدام أربعة ألوان مميزة تسهل توزيع الدعم والإنقاذ.'
    },
    {
      'question': 'ما دلالات الألوان الأربعة لبطاقات الفرز (Triage Tags) المعتمدة بنقاط الفرز الحربي؟',
      'answer': 'الأحمر: إصابة حرجة عاجلة تتطلب تدخلاً فورياً وبزل صدر لإنقاذ الوعي؛ الأصفر: إصابة جادة غير مهددة فوراً بالحياة ويمكن تأخير علاجها قليلاً؛ الأخضر: جريح طفيف يمشي ويمكن الاستعانة به؛ الأسود: متوفى أو إصابة ميئوس منها تقنياً بالنظر للموارد.'
    },
    {
      'question': 'كيف يتم تنظيم وتدبير تدفق واتجاه الجرحى داخل مركز طبي ميداني أثناء حادث جماعي (MASCAL)؟',
      'answer': 'يتم بتدفق حاد ذي اتجاه واحد غير متقاطع (One-way triage flow): مدخل خارجي للفرز، يليه مناطق المعالجة الحمراء ثم الصفراء، ثم منطقة الانتظار والإخلاء، للتخلص من عنق الزجاجة وصيانة الزمن.'
    },
    {
      'question': 'ما هو التقرير الطبي الموحد للإخلاء الطبي والتأمين التكتيكي المعروف بـ MIST؟',
      'answer': 'يتألف من 4 تفاصيل: M (Method of Injury - آلية حدوث الإصابة)، I (Injuries Sustained - نوع وتفصيل الجروح الملاحظة)، S (Signs & Symptoms - العلامات الحيوية والضغط والوعي والنبض)، T (Treatments Given - العلاجات المقدمة والتورنيكيت والأدوية).'
    },
    {
      'question': 'ما هي بطاقة معالجة الجرحى الميدانية التكتيكية MIST-AT ومحتويات تفاصيلها العميقة؟',
      'answer': 'تعتمد تفاصيل MIST الأساسية مضافاً إليها: A (Allergies - تفاعلات الحساسية المعروفة للجريح)، T (Time of treatments - الوقت بالتدقيق لتركيب التورنيكيت وحقن حمض TXA لمنع المهل وموت الخلايا).'
    },
    {
      'question': 'كيف يتم حماية وتنظيم مستودع مخازن أدوية الخندق من الغارات الرادارية والحرائق المفاجئة؟',
      'answer': 'بحفر مخازن صخرية تحت الأرض ومغارات طبيعية مدعمة بدعامات خرسانية، توجيه شبكات تهوية طبيعية مغلقة، واستعمال عوازل الرادار والأسلاك الشائكة وقائياً.'
    },
    {
      'question': 'ما هي معايير ترحيل وإخلاء جريح حربي بواسطة الإخلاء الطبي الجوي (MEDEVAC/CASEVAC)؟',
      'answer': 'استقرار السيطرة على مجرى الهواء الرئوي بالكامل، إمكانيات بزل الصدر الحيوية منجزة، النبض والدوران مستقس بضغط مقبول، تدوين تقارير التسليم الطبي MIST بدقة، وحزم المصاب لمنع تجلط الصقيع.'
    },
    {
      'question': 'كيف تدبر عملية توزيع وتدبير سرايا المسعفين بمسرح العمليات لضمان حيوية الاستجابة؟',
      'answer': 'بنظام خلايا إسعاف متقدم (3 إلى 4 مسعفين لكل فصيل) مرتبطة بشكل لاسلكي آمن مع النقاط الطبية بالكتائب، وضمان مناوبات صارمة لحماية المسعفين من فرط الإعياء البشري.'
    },
    {
      'question': 'ما هو دور التدريب العسكري السنوي المشترك على سيناريو إصابات جماعية (Combat Triage Simulation)؟',
      'answer': 'يهدف لبناء التنسيق البشري واللساني المتكامل للفرق الجراحية والإسعافية والاتصال مع سرايا الإخلاء، لتقليص زمن الاستجابة والفرز وصيانة الأرواح من الفوضى بالمعارك الحقيقية.'
    },
    {
      'question': 'كيف تتعامل إدارياً مع نفاد المحاليل والإبر واللوازم الحيوية بمركز طبي محاصر تكتيكياً؟',
      'answer': 'تفعيل بروتوكول الرعاية المقيدة والتقنين الصارم والتبرع الطبي بالدم الكامل الطازج، صيانة اللوازم المستعملة بالتعقيم كيميائياً وإدارياً، واستدعاء مروحيات الدعم والمظلات التموينية.'
    },
    {
      'question': 'كيف يتم حساب مدة الرعاية المطولة (Prolonged Field Care - PFC) لإنقاذ الجرحى بالخنادق المحاصرة بمحيط الدبلوم؟',
      'answer': 'هي القدرة على صون حياة وعناية المريض تحت الحصار من غياب الطيران النقال، لفترات تبدأ من 12 ساعة وتمتد لـ 72 ساعة عبر رصد المحاليل ومنع تدمير الصقيع والتقنيات المحمولة.'
    },
    {
      'question': 'ما هو الترميز اللوني والمستشار لإخلاء جرحى الجيش الوطني؟',
      'answer': 'يتم بفريد ترميز بطاقات الفرز لتوضع كأساور بلاستيكية بالمعصم أو تعليقها بالصدر لضمان بقائها وثباتها أثناء الزحف والرحلات النقلية الشاقة بساحات الوغى.'
    },
    {
      'question': 'بماذا تختص وثيقة الـ NATO/JTS CPGs العسكرية المرجعية لدبلوم الإسعاف الحربي؟',
      'answer': 'هي المرجعية الإجراءات التكتيكية الطبية التي تثبت معايير ضبط النزف الممنهج والتسكين، نقل الدماء وعمليات رعاية الفرز والحوادث الجماعية بالبيئات والدوريات العسكرية العاتية.'
    },
    {
      'question': 'ما الفارق بين إخلاء طبي تكتيكي (MEDEVAC) وتسلل إسعافي حقل رعاية مصابين (CASEVAC)؟',
      'answer': 'MEDEVAC تدار بواسطة ناقلات ومركبات مجهزة طبياً بوجود طاقم مسعفين معتمدين؛ أما CASEVAC فتدار بوسائل نقل عادية غير مجهزة عابرة للجبهات (كتف، خيل، مدرعات عادية) للساتر الآمن.'
    },
    {
      'question': 'كيف يتم ملء سجل المهارات العملياتية (Logbook) لطلاب دبلوم الاسعاف الحربي؟',
      'answer': 'يدون كل طالب الإجراءات الخمسين المنجزة تحت إشراف الجراح وميسر الكلية، مع تبيان النتائج، توثيق الصعوبات وتوقيع الضابط الطبيب الميداني كشرط إلزامي وبوابة للتخرج.'
    },
    {
      'question': 'ما هي المراجعة اللائحية السنوية لخطط الإبادة وإخراج الجرحى بالمعهد الطبي العسكري باليمن؟',
      'answer': 'دراسة الإحداثيات وتحديث مسارات ونقاط التطهير مع الفحص الدوري للسيارات الإسعافية لتقليص فاقد الأرواح في كشوفات النقل الطويل.'
    },
    {
      'question': 'كيف يتم التعامل بفرز START مع مصاب يتنفس بمعدل 45 نفساً بالدقيقة بالساحة؟',
      'answer': 'يصنف فوراً ببطاقة حمراء (Urgent/Critical) دون استكمال باقي الفحوصات لأن تسارع التنفس فوق 30 يدل على نقص بليغ وتأزم دوران الرئتين الحاسم.'
    },
    {
      'question': 'ما هو دور الضابط المستشار الطبي في إدارة تفشي وباء الجمرة بالخنادق؟',
      'answer': 'وضع خطط مكافحة الفئران، تتبع مصادر المياه، تقليص فترات تواصل الجنود مع الماشية البرية، وتأمين اللقاحات الكيميائية والدروع التنفسية لكتب الدفاع.'
    },
    {
      'question': 'كيف يتم تطهير السرير الجراحي للخيمة الطارئة بين عمليات جراحية متتالية بمأزق حاد؟',
      'answer': 'بالرش الغزير بمحلول الهيبوكلوريت والمسح الحاد بالمعقمات الكيميائية ذات التأثير الفوري، والغيار الشامل المعقم لملابس والصفائح لتفادي تلوث الدم.'
    },
    {
      'question': 'ما هو مفهوم رعاية التحكم بالضرر الميداني الكلي (Damage Control Resuscitation - DCR)؟',
      'answer': 'هو إرساء نظام إسعافي وعلاجي غرضه صيانة كفاءة الدم والصفائح دون تشتيتها بغير دم كامل، وإغلاق النزوف وتهوية الرئتين وحفظ البدن لمنع الوفاة السريعة.'
    },

    // === Medical Terminology, Military Arab/English abbreviations, and MIST-AT cards (171-185) ===
    {
      'question': 'ما معنى المصطلح الطبي اللاتيني "Sepsis" وما مسبباته السريرية بالدبلوم؟',
      'answer': 'الشلل والتعفن الجرثومي بالدم (إنتان الدم) نتيجة تغلغل البكتيريا والسموم من الجروح المتسخة إلى مجرى الدم مؤدية إلى هبوط الضخ وفشل الأعضاء حاد الصعوبة.'
    },
    {
      'question': 'ما دلالة الاختصار الطبي العسكري الشائع FAST في تشخيص نزف الجرحى؟',
      'answer': 'هو تقييم فحص الصدر والبطن بالموجات فوق الصوتية الطارئ والموجه (Focused Assessment with Sonography for Trauma) للكشف السريع عن تجمعات الدماء بمحيط القلب والكبد وبوابات الحوض.'
    },
    {
      'question': 'ما معنى السابق اللاتينية الحفرية Hypo واللاحقة Emia بالرموز الطبية؟',
      'answer': 'Hypo تعني القلة أو الانخفاض للمستوى المطلوب، وEmia تعني الدم أو الوجود في الشرايين، وبالمزج يتشكل Hypo-volemia انخفاض حجم الدوران بالدم جراء النزف.'
    },
    {
      'question': 'ما المقصود باختصار TCCC أو T3C الشائع بمسائل المعهد الطبي الحربي؟',
      'answer': 'هو دليل الرعاية التكتيكية لإصابات المعارك العسكرية (Tactical Combat Casualty Care) المنظم لإجراءات ومراحل إنقاذ جرحى الحروب والخطوط الدفاعية بمهارة وحسم.'
    },
    {
      'question': 'كيف تفسر رمز وبطاقة التسليم MIST-AT في إطار إرسال المراسلات والبرقيات اللاسلكية؟',
      'answer': 'تُرسل كرسالة بروقية قصيرة ومحددة بنطاق عاجل لإعلام المشفى الميداني المستقبل ليتسنى له تهيئة دم كافٍ، توجيه الأطباء الجراحين وتجهيزات الإخلاء.'
    },
    {
      'question': 'ما معنى المصطلح "Apnea" ورمز السابقة النافية "A" بالرعايات الرئوية؟',
      'answer': '"A" تعني النفي أو الانعدام الكلي، و"Pnea" تعني التنفس، وبدمجها Apnea يتشكل "انقطاع وتوقف التنفس والجهد الرئوي الحاد" المستدعي للإنعاش السريع.'
    },
    {
      'question': 'ما دلالة الحروف الكيميائية WMD في الصياغات العسكرية بالكلية؟',
      'answer': 'هي أسلحة الدمار الشامل (Weapons of Mass Destruction) المشتملة على العوامل الكيماوية والمولودة بيولوجياً والمفاعلات النووية المضرة بالمدن والجبهات.'
    },
    {
      'question': 'ما معنى اللاحقة الطبية اللاتينية "itis" وما دلالتها بفحوص الجراح؟',
      'answer': 'تعني حدوث التهاب أو رد فعل مناعي موضعي حاد ومزمن بالأغشية، مثل Appendicitis (التهاب الزائدة الدودية) أو Peritonitis (التهاب الصفاق البطني العام).'
    },
    {
      'question': 'ما معنى الكلمة الفسيولوجية "Hemostasis" والفرق الصياغي بينها وبين "Homeostasis"؟',
      'answer': '"Hemostasis" تعني وقف النزيف والسيطرة الدموية الحاقرة لسلامة الأوعية؛ أما "Homeostasis" فتعني ترطيب وتوازن البيئة الداخلية والخلوية للبدن ككل.'
    },
    {
      'question': 'ما المقصود بالرمز الطبي العسكري REBOA وأهميته وجراحة جرحى البطن؟',
      'answer': 'هو شق وإدخال قسطرة شريانية بالبالون لداخل الشريان الأبهر الصدري (Resuscitative Endovascular Balloon Occlusion of the Aorta) لقطع النزيف الحوضي والبطني القاتل مؤقتاً.'
    },
    {
      'question': 'ما معنى السلاح الطبي الرمزي "POCUS" في ساحات الكلية ومشافي الجبهات باليمن؟',
      'answer': 'هو جهاز فحص السونار المحمول باليد والموجه سريرياً بساحة القتال (Point-of-Care Ultrasound) للتقييم الفوري للنزف الداخلي واسترواح الرئتين.'
    },
    {
      'question': 'ما معنى اللاحقة "ectomy" والصياغة الطبية لعمليات "Splenectomy"؟',
      'answer': '"ectomy" تعني نزع واستئصال جراحي كلي للغضو؛ وSplenectomy تعني الاستئصال الفوري للمستودع الطحالي المتمزق نتيجة للشظايا لمنع هبوط الدوران الصاعق للوفاة.'
    },
    {
      'question': 'ما معنى المصطلح اللاتيني "Myocardium" وتدابير ومركبات إنعاشه الفوري؟',
      'answer': 'يعني عضلة وجدار القلب الحيوية المعنية بعملية الضخ الشرياني، وإنعاشه يتم بنبضات الـ CPR والإنعاش القلبي الحاقر للأصوات الكلية.'
    },
    {
      'question': 'ما أهمية تعريب المصطلحات والرموز الأجنبية ودورها بـ "اللغة العربية والتحرير العسكري"؟',
      'answer': 'لبناء بروتوكول اتصال معجمي ولغوي وطني موحد بالكتائب والقوات المسلحة يمنع اللبس والترجمة الخاطئة بالأوقات الصعبة للتنسيق الدفاعي.'
    },
    {
      'question': 'ما معنى اللفظ اللاتيني "Edema" وما الممارسات التمريضية لملاحظته بالساقين؟',
      'answer': 'يعني ارتشاح وتجمع مائي وسوائل خلايا الشرايين بالأنسجة الرخوة (الوذمة والورم السائل بالمفاصل)، ويقاس بالفحص بالإصبع وملاحظة الانخفاض الجلدي المتبقي.'
    },

    // === Quranic Culture, Faith-based Combat ethics and Medical Code of Conduct (186-200) ===
    {
      'question': 'كيف يستمد الكادر الطبي الحربي معاني وثقافة الصمود والإحسان من القرآن الكريم والنهج الجهادي باليمن؟',
      'answer': 'يستمدها باستشعار المسؤولية الكبرى أمام رب العزة بكون إنقاذ حياة المقاتلين جرحى الإباء عملاً جهادياً مقدساً وذروة سنام الفخر والوفاء، عملاً بقوله تعالى: {وَمَنْ أَحْيَاهَا فَكَأَنَّمَا أَحْيَا النَّاسَ جَمِيعاً}.'
    },
    {
      'question': 'ما هي الأمانة الأخلاقية والمهنية للمسعف الحربي بساحات المعارك بنهج الشهيد زيد طاووس؟',
      'answer': 'تتمثل في تقديم الرعاية والمداواة لكافة المرضى والجرحى بإخلاص وتفانٍ مطلقين دون تمييز أو وهن، وتسخير السلاح الطبي وموارد الإسعاف لحماية الروح والجسد وبث الطمأنينة والإيمان بنصر الله.'
    },
    {
      'question': 'ما دور المنهج الجهادي والقرآني في تثبيت عزيمة الكادر الطبي بالخطوط المتقدمة والمحاصرة؟',
      'answer': 'يرسخ الإيمان الصادق بأن الحياة والموت بيد الله، وأن ما يصيب العبد في سبيل مداواة جرحى الدفاع ينال به رفيع الدرجات بالفردوس، مما يورث هدوءاً وثباتاً ورباطة جأش تكتيكية بالغة بساحة الوغى.'
    },
    {
      'question': 'كيف يحافظ المسعف العسكري على خصوصية وكرامة الجريح أثناء إسعافه بالخنادق الساخنة؟',
      'answer': 'بتجنب تجريد الجسد من الملابس إلا للضرورة الطبية القصوى الكاشفة لمداخل الرصاص، معاملته برأفة بالغة، صون سره، واجتناب نشر أو تصوير ندباته دون مسوغ شرعي وعسكري.'
    },
    {
      'question': 'ما هو التوجيه القرآني الصارم للتعامل الطبي والإنساني مع جرحى الأعداء المقبوض عليهم والأسارى؟',
      'answer': 'يعالج جروح الأسرى والمصابين من الأعداء بأمانة وأخلاق الإسلام والقرآن الكريم وعاطفة المحاسبة والإحسان، عملاً بقوله تعالى: {وَيُطْعِمُونَ الطَّعَامَ عَلَى حُبِّه بَعِيداً مِسْكِيناً وَيَتِيماً وَأَسِيراً} وتلافي أي غدر أو تمثيل.'
    },
    {
      'question': 'كيف يسهم الانضباط الأخلاقي والعسكري لكوادر الدبلوم بالتقليص الفعلي لفاقد الجرحى؟',
      'answer': 'الانضباط الصارم بقوانين الكرامة وطاعة القيادة يمنع الاجتهادات المرتجلة الخاطئة، ويرص بناء الكتائب الطبية تلاحماً يحفظ الأرواح والتموين بنمط متناغم حكيم.'
    },
    {
      'question': 'ما وظيفة الصلاة والدعاء والتعليم القرآني اليومي بمواقع المعهد الطبي باليمن؟',
      'answer': 'غسل وتطهير القلوب من ركام الخوف والإحباط، وبناء العقيدة الجهادية الصلبة اللازمة لمواجهة الصعاب والصمود بوجه المعتدين وأعداء الإنسانية.'
    },
    {
      'question': 'كيف يؤصل المنهج القرآني خلق الصبر {وَالصَّابِرِينَ فِي الْبَأْسَاءِ وَالضَّرَّاءِ} كأداة حيوية للمسعف الحربي؟',
      'answer': 'الصبر يمنح المسعف الحصانة النفسية لتقبل هول تهتك الأشلاء والدماء الحامية، ويمكنه من الحفاظ على هدوء يديه الذهبي والتشغيل الدقيق للإبر بالتنفس.'
    },
    {
      'question': 'ما هي الأمانة الجهادية في التوثيق الطبي العادل لكشوف وحقوق الشهداء والجرحى؟',
      'answer': 'التوثيق العلمي الدقيق غير المحابي لكل التدخلات والإصابات وبطاقات الفرز صوناً لحقوق أسر الشهداء والجرحى لدى دافع الصحة وضمان وصول الحق لصاحبه كاملاً.'
    },
    {
      'question': 'ما المقصد الديني والعلمي لمعاني "الإحسان" المذكور بآيات المنهج المطبقة بالدبلوم؟',
      'answer': 'الإحسان هو القيام بالواسطات الجراحية والمداواة بمستويات فائقة الجودة والدقة والمهارة، لا بدافع الواجب الوظيفي الضيق، بل تقرباً وتعظيماً لله وللخلق.'
    },
    {
      'question': 'كيف يتعامل الكادر الطبي مع حالات الهلع والتطاول اللفظي للجرحى تحت تأثير صدمات قمع الانفجار؟',
      'answer': 'بالتجاوز والصبر المنهجي والاستماع المحب وطرد نزغات الخوف وتثبيت سريرتهم بآيات الله والأحاديث الناطقة بالصمود والانتصار.'
    },
    {
      'question': 'ما هو الحكم الشرعي والعسكري للتخاذل والفرار من إسعاف ومساندة جريح بالجبهة؟',
      'answer': 'يعتبر من كبائر الغدر العسكري والفرار من الزحف والتخلي البليغ عن الواجب الجهادي والضمير الإنساني والمهني، ويترتب عليه عقوبات حازمة دنيا وآخرة.'
    },
    {
      'question': 'كيف تغرس الثقافة القرآنية والوفاء مبدأ عدم التفرقة والشفافية بنقاط ومشافي الكلية الميدانية؟',
      'answer': 'تفرض قواعد متسقة للفرزSTART والتقديم العلاجي استناداً للأولويات الطبية المنقذة للأطقم والمجهود دون محسوبيات أو تخاذل لضمان العدالة.'
    },
    {
      'question': 'بروز وقدوة الطبيب الشهيد زيد طاووس كأنموذج للعمل الطبي والجهادي الملتزم باليمن؟',
      'answer': 'كان مثالاً وملاذاً للجرحى والمستضعفين يسخّر علمه الطبي وعقيدته الجهادية لخدمتهم بالرمق الأخير نهاراً ومساءً صوناً للوطن والمنهج والمسؤولية.'
    },
    {
      'question': 'المنظومة الأخلاقية للتعامل مع النفايات الطبية والأماكن بمواقع المعارك وفق الإعزاز القرآني؟',
      'answer': 'الحرص البالغ على بقاء ونظافة الحقول الطبية والمغارات وعدم تلويث البيئة أو الآبار بالفضلات بل معالجة وطمر المحتويات بانتظام حكيم وإعزاز كامل.'
    },

    // === Advanced TCCC Scenarios & Pitfalls (201-230) ===
    {
      'question': 'ما هي المخاطر المحتملة لاستخدام التورنيكيت بشكل خاطئ؟',
      'answer': 'تشمل: عدم السيطرة الكاملة على النزيف لعدم شده بقوة كافية، إصابة الأعصاب الطرفية نتيجة الضغط الزائد، تلف الأنسجة تحت الرباط، وظهور متلازمة الحيز إذا بقي لمدة طويلة دون داع.'
    },
    {
      'question': 'كيف تتعامل مع جريح فاقد للوعي في مرحلة الرعاية تحت النار (CUF)؟',
      'answer': 'لا تقم بإجراءات متقدمة، فقط اسحب المصاب إلى ساتر آمن إن أمكن، وركب تورنيكيت على الأطراف التي تنزف بشدة، ثم استمر في الاشتباك حتى يصبح الوضع آمناً لتطبيق الرعاية الكاملة.'
    },
    {
      'question': 'ماذا تفعل إذا لاحظت انتفاخاً تحت الجلد (Subcutaneous Emphysema) بعد تركيب أنبوب صدري؟',
      'answer': 'أعد تقييم وضع الأنبوب والتوصيلات، تأكد من عدم انسداد الصمام، وإذا استمر الانتفاخ دل ذلك على تسرب هوائي كبير قد يستدعي أنبوباً ثانياً أو تدخلاً جراحياً.'
    },
    {
      'question': 'لماذا تعتبر إبرة بزل الصدر القياسية (3.25 إنش) غير كافية أحياناً لدى المصابين ذوي البنية الضخمة؟',
      'answer': 'لأن سماكة جدار الصدر قد تتجاوز طول الإبرة فلا تصل للتجويف الجنبي، لذا توصي البروتوكولات الحديثة باستخدام إبر أطول (مثلاً 3.5 إنش) أو موقع الإبط الأمامي بديلاً.'
    },
    {
      'question': 'ما مؤشرات فشل تأمين المجرى الهوائي عبر الأنبوب الأنفي البلعومي (NPA)؟',
      'answer': 'عدم تحسن التشبع بالأوكسجين، استمرار الشخير أو انسداد النفس، نزف أنفي حاد، أو عدم تحمل المريض للأنبوب، مما يستوجب الانتقال الفوري إلى تقنية أكثر تقدماً كالجراحة الحلقية الدرقية.'
    },
    {
      'question': 'ما خطورة تحويل التورنيكيت إلى ضمادة ضاغطة في وقت مبكر جداً قبل اكتمال تخثر الدم؟',
      'answer': 'قد يؤدي إلى إعادة النزيف الغزير وتعريض حياة المصاب للخطر، لذا يجب التأكد من ثبات الجلطة وعدم وجود صدمة نزفية قبل محاولة التحويل.'
    },
    {
      'question': 'كيف تدير إصابة مزدوجة: استرواح صدري ضاغط ونزف حاد في الطرف نفسه؟',
      'answer': 'وفق أولويات MARCH: تعامل فوراً مع النزف بالتورنيكيت، ثم بزل الصدر لتخفيف الضغط، ثم تقييم الدورة الدموية، لأن النزف الصاعق يقتل أسرع من الاسترواح.'
    },
    {
      'question': 'لماذا قد يسبب بزل الصدر بالإبرة في موقع خاطئ إصابة مميتة؟',
      'answer': 'إذا تم البزل قريباً جداً من عظم القص أو أسفل الضلع، قد يصاب الشريان الثديي الداخلي أو القلب أو الأوعية الكبرى، مما يؤدي لنزف داخلي هائل.'
    },
    {
      'question': 'ما هي علامات متلازمة الحيز (Compartment Syndrome) في الطرف المصاب وكيف تشخص ميدانياً؟',
      'answer': 'ألم شديد غير متناسب مع الجرح، تيبس وشد في العضلات، وخز وتنميل، غياب النبض في مراحل متقدمة. ويقاس الضغط داخل الحيز بجهاز خاص إذا توفر، وإلا فالتشخيص سريري.'
    },
    {
      'question': 'ماذا تفعل إذا كان المصاب يرتدي خوذة واقية وتعاني من صعوبة في تأمين مجرى الهواء؟',
      'answer': 'تثبت الرقبة يدوياً من قبل مساعد، ثم تفك الخوذة بحذر مع الحفاظ على استقامة العمود الفقري، ثم تنزع لإتاحة الوصول للمجرى الهوائي دون التسبب في إصابة نخاعية.'
    },
    {
      'question': 'كيف تتعامل مع مريض يعاني من نزف حاد في الرقبة لا يمكن ضغطه بالضمادات المرقئة العادية؟',
      'answer': 'تستخدم ضمادة مرقئة (Hemostatic Gauze) وتعبئ الجرح بها بإحكام، ثم تضع ضمادة ضاغطة فوقها وتثبتها بشريط لاصق مع تجنب الضغط على القصبة الهوائية والأوعية الدموية الرئيسية.'
    },
    {
      'question': 'ما هو بروتوكول إعادة التقييم بعد تنفيذ تدخلات MARCH كاملة؟',
      'answer': 'تعيد تقييم جميع التدخلات بالترتيب M-A-R-C-H كل 5-10 دقائق أو عند أي تغير في حالة المصاب، للتأكد من استمرارية فعاليتها وعدم حدوث مضاعفات جديدة.'
    },
    {
      'question': 'لماذا يجب تجنب رفع ساقي المصاب في صدمة نزفية كطريقة قديمة؟',
      'answer': 'لأن رفع الساقين لا يحسن العائد الوريدي بشكل فعال وقد يزيد من الضغط داخل البطن ويعيق التنفس، كما قد يحرك جلطات حديثة. البروتوكولات الحديثة تفضل السوائل الوريدية الحذرة ونقل الدم.'
    },
    {
      'question': 'ما هي أولويات العناية بالمصابين في البيئات الجبلية الباردة إضافة إلى MARCH؟',
      'answer': 'إضافة الحماية من انخفاض الحرارة (Hypothermia) بشكل مبكر، بتغطية المصاب بأغطية حرارية فوراً، تسخين السوائل الوريدية قبل إعطائها، وعزل المريض عن الأرض الباردة.'
    },
    {
      'question': 'كيف تتعرف على إصابة الرئة الانفجارية (Blast Lung) في الميدان؟',
      'answer': 'بوجود ضيق تنفس مفاجئ بعد الانفجار، سعال دموي، ألم صدري، نقص تشبع الأوكسجين، مع علامات وذمة رئوية. ويحتاج المصاب إلى أكسجين عالي التدفق ودعم تنفسي فوري.'
    },
    {
      'question': 'ماذا يميز إصابة العين النافذة عن غير النافذة في الفرز الميداني؟',
      'answer': 'في النافذة: تظهر فتحة ظاهرة في كرة العين مع تسرب سوائل، ألم شديد، وتشوش رؤية حاد. تغطى بغطاء صلب واقٍ للعينين معاً لمنع حركة العين المصابة، ولا يضغط عليها بتاتاً.'
    },
    {
      'question': 'ما هي خطوات تحويل التورنيكيت إلى ضمادة ضاغطة بأمان في مرحلة الرعاية الميدانية (TFC)؟',
      'answer': '1. التأكد من استقرار المصاب وعدم وجود صدمة. 2. تركيب ضمادة مرقئة على الجرح مباشرة. 3. فك التورنيكيت ببطء مع ملاحظة النزف. 4. إذا حدث نزف نشط، يعاد شد التورنيكيت فوراً.'
    },
    {
      'question': 'كيف تتعامل مع إصابة انزياحية في العمود الفقري لمصاب فاقد للوعي؟',
      'answer': 'تثبيت الرأس والرقبة يدوياً في الوضع المحايد، استخدام طوق رقبة صلب، ونقل المصاب على لوح صلب طويل مع تثبيت كامل للجسم، وتجنب أي ثني أو دوران للعمود الفقري.'
    },
    {
      'question': 'ما هو الحد الأدنى من المعدات التي يجب أن يحملها المسعف الحربي في جعبته الإسعافية؟',
      'answer': 'تورنيكيتان على الأقل، ضمادات مرقئة، ضمادات ضاغطة، ضماد صدري بصمام، إبر بزل الصدر، أنبوب أنفي بلعومي، قفازات، مقص، وبطانية حرارية، بالإضافة إلى مسكنات الألم الميدانية.'
    },
    {
      'question': 'كيف تعدل خطة العلاج إذا كان المصاب يعاني من حساسية معروفة للكيتامين؟',
      'answer': 'تجنب الكيتامين تماماً واستخدم بديلاً مثل الفنتانيل بجرعات مخفضة مع مراقبة دقيقة للتنفس، أو استخدم التسكين غير الدوائي كالتثبيت الجيد والتبريد الموضعي إن أمكن.'
    },
    {
      'question': 'ما هي التحديات الخاصة بإسعاف الجرحى في الظلام الدامس ليلاً؟',
      'answer': 'استخدام الإضاءة الحمراء الخافتة (لتجنب كشف الموقع)، الاعتماد على اللمس لتقييم النزيف، تجهيز المعدات مسبقاً في أماكن يسهل الوصول إليها، والعمل ضمن فريق مع توزيع أدوار دقيقة.'
    },
    {
      'question': 'لماذا يمنع استخدام المقص العادي لقص الملابس عن المصاب في بيئة ملوثة كيميائياً؟',
      'answer': 'لأن قص الملابس قد يثير الغبار والجسيمات السامة ويعيد تعليقها في الهواء مما يعرض المسعف والمصاب لخطر الاستنشاق، بل يجب نزع الملابس بحذر وبأقل قدر من الاهتزاز.'
    },
    {
      'question': 'كيف تتعرف على علامات الصدمة العصبية (Neurogenic Shock) لدى مصاب العمود الفقري؟',
      'answer': 'هبوط ضغط الدم مع بطء نبض (Bradycardia) غير مناسب، جلد دافئ وجاف أسفل مستوى الإصابة، وفقدان التوتر العضلي، نتيجة انقطاع الإشارات العصبية الودية.'
    },
    {
      'question': 'ما هي أولى الخطوات عند الاشتباه بإصابة دماغية رضية (TBI) في الميدان؟',
      'answer': 'تقييم مستوى الوعي بمقياس غلاسكو، فحص الحدقتين وتفاعلهما مع الضوء، تأمين مجرى الهواء والتنفس، تجنب نقص الأوكسجين أو هبوط الضغط، وتوثيق أي تدهور عصبي.'
    },
    {
      'question': 'ما هي أبرز الفروقات في إسعاف جريح من القوات الصديقة وآخر من المدنيين في النزاعات؟',
      'answer': 'لا فروقات طبية، فالرعاية تقدم للجميع وفق البروتوكول ذاته، لكن قد تختلف إجراءات التوثيق الأمني والإخلاء حسب القواعد العسكرية المنظمة للعمليات.'
    },
    {
      'question': 'كيف يتم التعامل مع مصاب يعاني من توقف القلب والتنفس نتيجة صاعقة كهربائية في الميدان؟',
      'answer': 'التأكد من إبعاد المصدر الكهربائي، بدء الإنعاش القلبي الرئوي فوراً (CPR) مع مزيل الرجفان الآلي (AED) إن توفر، لأن الصاعقة غالباً ما تسبب رجفاناً بطينياً قابلاً للعلاج.'
    },
    {
      'question': 'ماذا تعني قاعدة "الذهبيات الخمس" في فحص المسعف لمعداته قبل الخروج للدورية؟',
      'answer': 'التأكد من وجود: 1. تورنيكيت جاهز، 2. ضمادات مرقئة، 3. أدوات مجرى هواء، 4. وسائل بزل الصدر، 5. أدوية الطوارئ. وفحص سلامتها وتواريخ صلاحيتها.'
    },
    {
      'question': 'كيف تسعف مصاباً عضته أفعى سامة في بيئة جبلية نائية؟',
