      'answer': 'عمر النصف هو الوقت اللازم لينخفض تركيز الدواء في الدم إلى النصف. أهميته: 1. يحدد عدد مرات إعطاء الدواء يومياً. 2. الأدوية ذات عمر النصف القصير (مثل الأدرينالين: دقائق) تحتاج لتكرار أو تسريب مستمر. 3. الأدوية ذات عمر النصف الطويل (مثل الأزيثروميسين: 68 ساعة) تعطى مرة واحدة يومياً.'
    },
