    {
      'question': 'ما أنواع الأشكال الصيدلانية التي يتعرف عليها المسعف الحربي في هذا المقرر؟',
      'answer': '1. الأمبولات (Ampoules): زجاجية محكمة الإغلاق، تُكسر للاستخدام. 2. القوارير (Vials): زجاجة بغطاء مطاطي، يُسحب منها الدواء. 3. الأقراص والكبسولات. 4. البخاخات (Inhalers). 5. المراهم والكريمات. 6. المحاليل الوريدية في أكياس أو زجاجات. 7. أمبولات مملوءة مسبقاً (Prefilled Syringes) مثل حقن الأتروبين الذاتية.'
    },
    {
      'question': 'كيف تختار طريقة إعطاء المسكن المناسبة في بيئة القتال؟',
      'answer': 'في مرحلة الرعاية تحت النار (CUF): لا تعط أي دواء، فقط أنقذ المصاب. في مرحلة الرعاية الميدانية (TFC): تبدأ بالطريق الوريدي أو داخل العظم (IV/IO) إذا كان المصاب في صدمة أو الألم شديد، فتعطي المورفين أو الكيتامين. وإذا كانت حالة المصاب مستقرة والألم متوسط، يمكن إعطاء الفنتانيل الفموي المحلى (OTFC) أو حبة ترامادول فموية.'
    },

    // ========== 81-95: الجرعات الدوائية وحسابها ==========
    {
      'question': 'ما تعريف الجرعة الدوائية وما أنواعها؟',
      'answer': 'الجرعة هي كمية الدواء التي تعطى للمريض لتحقيق التأثير العلاجي. أنواعها: 1. جرعة البدء (Loading Dose): جرعة أولية عالية لرفع تركيز الدواء سريعاً. 2. جرعة الصيانة (Maintenance Dose): جرعة مستمرة للحفاظ على التركيز العلاجي. 3. الجرعة القصوى (Maximum Dose): أعلى جرعة آمنة. المسعف يلتزم بالجرعات الموصى بها في بروتوكولات TCCC.'
    },
    {
      'question': 'كيف تحسب جرعة الدواء بناءً على وزن المصاب؟',
      'answer': 'القاعدة: الجرعة (ملغ) = وزن المصاب (كغ) × الجرعة الموصى بها لكل كيلوغرام (ملغ/كغ). مثال: إذا كان وزن المصاب 70 كغ، والجرعة الموصى بها من الكيتامين للتخدير هي 1-2 ملغ/كغ، تكون الجرعة = 70 × 2 = 140 ملغ كحد أقصى. هل تريد مثالاً على حساب جرعة الأدرينالين؟'
    },
    {
      'question': 'كيف تحسب جرعة الأدرينالين لمصاب بالغ بصدمة تحسسية؟',
      'answer': 'الجرعة القياسية للبالغ: 0.3-0.5 ملغ من محلول 1:1000 (أي 0.3-0.5 مل) تحقن في العضلة الفخذية الوحشية (IM). إذا حسبنا بالوزن (0.01 ملغ/كغ): لمصاب وزنه 80 كغ، الجرعة = 80 × 0.01 = 0.8 ملغ، لكن الحد الأقصى 0.5 ملغ للجرعة الواحدة. فتعطيه 0.5 ملغ. تكرر كل 5-15 دقيقة إذا لم يستجب.'
    },
    {
      'question': 'كيف تحسب جرعة المورفين الوريدي لتسكين الألم في الميدان؟',
      'answer': 'الجرعة الموصى بها في TCCC: 5 ملغ وريدياً (IV) أو داخل العظم (IO) ببطء. يمكن تكرارها كل 10 دقائق حتى يزول الألم أو يظهر تثبيط تنفسي (معدل التنفس < 12). لا تعطى إذا كان ضغط الدم الانقباضي أقل من 90 مم زئبق. الجرعة للأطفال: 0.1-0.2 ملغ/كغ.'
    },
    {
      'question': 'ما العوامل التي تؤثر على جرعة الدواء في الميدان؟',
      'answer': '1. وزن المصاب (الأهم). 2. العمر (الأطفال والمسنون يحتاجون جرعات أقل). 3. وظائف الكلى (إذا كانت ضعيفة، نقلل الجرعة). 4. وظائف الكبد (إذا كانت ضعيفة، نتجنب الأدوية التي تستقلب كبدياً). 5. وجود أدوية أخرى (تفاعلات). 6. حالة الدورة الدموية (الصدمة تقلل الحاجة للتخدير).'
    },
    {
      'question': 'كيف تحسب جرعة المضاد الحيوي سيفترياكسون لعلاج التهاب رئوي في الميدان؟',
      'answer': 'الجرعة للبالغ: 1-2 غرام مرة واحدة يومياً، تعطى عضلياً (IM) أو وريدياً (IV). لالتهاب رئوي حاد، نستخدم 2 غرام. للأطفال: 50-75 ملغ/كغ/يوم. يحل المسحوق في 3.5 مل من الليدوكائين 1% للحقن العضلي (لتخفيف الألم).'
    },
    {
      'question': 'ما الفرق بين النسبة المئوية للمحلول وكمية الدواء الفعلية؟',
      'answer': 'المحلول 1% يعني أن كل 1 مل من المحلول يحتوي على 10 ملغ من المادة الفعالة. المحلول 1:1000 يعني أن كل 1 مل يحتوي على 1 ملغ. مثال: أمبولة أدرينالين 1:1000 حجمها 1 مل تحوي 1 ملغ أدرينالين. إذا أردت إعطاء 0.5 ملغ، تسحب 0.5 مل من الأمبولة.'
    },
    {
      'question': 'كيف تتجنب الأخطاء في حساب الجرعات تحت ضغط الميدان؟',
      'answer': '1. احفظ الجرعات الأساسية لأدوية الطوارئ عن ظهر قلب. 2. استخدم "شريط براسلو" (Broselow Tape) لتقدير وزن الأطفال. 3. اكتب الجرعة على جبين المصاب أو على شريط لاصق على صدره. 4. تحقق من الجرعة مع زميل إذا أمكن. 5. استخدم التطبيقات الذكية (مثل Epocrates) للتحقق.'
    },

    // ========== 96-110: أدوية الطوارئ (الأدرينالين، الأتروبين، النالوكسون، الكيتامين) ==========
    {
      'question': 'ما هي آلية عمل الأدرينالين (Adrenaline/Epinephrine)؟',
      'answer': 'الأدرينالين ناهض (منشط) لمستقبلات ألفا وبيتا الأدرينالية في الجسم. تأثيره على مستقبلات ألفا: يقبض الأوعية الدموية فيرفع ضغط الدم ويقلل التورم. تأثيره على مستقبلات بيتا-1: يزيد قوة وسرعة القلب. تأثيره على مستقبلات بيتا-2: يوسع القصبات الهوائية. هذه التأثيرات الثلاثية تجعله الدواء المنقذ في الصدمة التحسسية والإنعاش القلبي الرئوي.'
    },
    {
      'question': 'ما دواعي استخدام الأدرينالين في الإسعاف الحربي؟',
      'answer': '1. الصدمة التحسسية (Anaphylaxis): هو الدواء الأول والمنقذ. 2. الإنعاش القلبي الرئوي (CPR): في توقف القلب. 3. الربو الحاد الشديد: عندما تفشل موسعات القصبات. 4. الصدمة الإنتانية: عند فشل السوائل في رفع الضغط.'
    },
    {
      'question': 'ما الآثار الجانبية والاحتياطات عند إعطاء الأدرينالين؟',
      'answer': 'الآثار الجانبية: تسارع شديد في القلب، ارتفاع ضغط الدم، قلق ورجفة، صداع. الاحتياطات: 1. الحقن العضلي في الفخذ هو الأفضل (أسرع امتصاصاً من الذراع). 2. تجنب الحقن الوريدي إلا في توقف القلب لأنه قد يسبب اضطرابات نظم قاتلة. 3. في المرضى كبار السن أو مرضى القلب، نبدأ بنصف الجرعة.'
    },
    {
      'question': 'ما هي آلية عمل الأتروبين (Atropine) واستخداماته في الميدان؟',
      'answer': 'الأتروبين هو مضاد لمستقبلات الأسيتيل كولين المسكارينية (Anticholinergic). استخداماته: 1. بطء القلب العرضي (Symptomatic Bradycardia): يمنع تأثير العصب الحائر على القلب فيسرع النبض. 2. التسمم بغازات الأعصاب (Nerve Agents): يمنع تأثير الأسيتيل كولين الزائد في المستقبلات. 3. تقليل الإفرازات قبل التنبيب.'
    },
    {
      'question': 'ما جرعة الأتروبين في بطء القلب وفي التسمم بغازات الأعصاب؟',
      'answer': 'في بطء القلب: 0.5-1 ملغ وريدياً، تكرر كل 3-5 دقائق حتى 3 ملغ كحد أقصى. في التسمم بغازات الأعصاب: الجرعة كبيرة وقد تصل إلى 2-6 ملغ وريدياً كل 5-10 دقائق حتى تجف الإفرازات الرئوية. المسعف يستخدم حقنة الأتروبين الذاتية (Auto-injector) التي تحوي 2 ملغ.'
    },
    {
      'question': 'ما هي آلية عمل النالوكسون (Naloxone) ومتى يستخدمه المسعف الحربي؟',
      'answer': 'النالوكسون هو معاكس تنافسي لمستقبلات الأفيون (Opioid Antagonist)، يزيح المورفين والأفيونات الأخرى من مستقبلاتها ويعكس تأثيرها. يستخدمه المسعف عند حدوث تثبيط تنفسي (معدل التنفس < 10) بعد إعطاء المورفين. الجرعة: 0.4-2 ملغ وريدياً أو عضلياً أو أنفياً، تكرر كل 2-3 دقائق. إذا استمر التثبيط التنفسي، هل تسأل عن الخطوات التالية؟'
    },
    {
      'question': 'ما الاحتياطات عند إعطاء النالوكسون لمصاب تلقى جرعة زائدة من المورفين؟',
      'answer': '1. النالوكسون قد يسبب أعراض انسحاب حادة (ألم شديد، هيجان، ارتفاع ضغط ونبض) لأنك أزلت فجأة تأثير المسكن. 2. مدة فعالية النالوكسون (30-90 دقيقة) أقصر من مدة المورفين (4-6 ساعات)، فقد يعود التثبيط التنفسي بعد زوال تأثير النالوكسون، فتحتاج لمراقبة مستمرة. 3. استخدم أقل جرعة فعالة (ابدأ بـ 0.4 ملغ) لتجنب أعراض الانسحاب الشديدة.'
    },
    {
      'question': 'لماذا يُفضل الكيتامين (Ketamine) على المورفين كمسكن في الصدمة النزفية؟',
      'answer': 'لأن الكيتامين يتميز بمزايا فريدة: 1. لا يسبب هبوطاً في ضغط الدم (بل قد يرفعه قليلاً) بينما المورفين يوسع الأوردة ويهبط الضغط. 2. لا يثبط التنفس بقوة مثل المورفين. 3. يوفر تسكيناً وتخديراً (Dissociative Anesthesia). 4. يوسع القصبات، مما يفيد في إصابات الصدر. لذلك هو الخيار الأول في TCCC للمصابين بصدمة نزفية.'
    },
    {
      'question': 'ما جرعة الكيتامين لتسكين الألم في الميدان وما آثاره الجانبية؟',
      'answer': 'جرعة التسكين: 0.3-0.5 ملغ/كغ وريدياً أو 0.5-1 ملغ/كغ عضلياً. الجرعة التخديرية: 1-2 ملغ/كغ وريدياً. الآثار الجانبية: هلوسة وأحلام يقظة (يمكن تقليلها بإعطاء ميدازولام)، زيادة إفرازات اللعاب والقصبات، ارتفاع ضغط العين والدماغ (فيمنع في إصابات العين المفتوحة وإصابات الرأس الشديدة).'
    },

    // ========== 111-130: المسكنات (الأفيونية وغير الأفيونية ومضادات الالتهاب) ==========
    {
      'question': 'قارن بين المورفين والترامادول والباراسيتامول من حيث القوة التسكينية.',
      'answer': 'المورفين: أقوى مسكن (أفيوني قوي)، يستخدم للآلام الشديدة (كسور، حروق، بتر). الترامادول: مسكن متوسط القوة (أفيوني ضعيف)، يستخدم للآلام المتوسطة. الباراسيتامول: مسكن ضعيف إلى متوسط (غير أفيوني)، يستخدم للآلام الخفيفة وكخافض حرارة. هل تريد معرفة الآثار الجانبية لكل منها؟'
    },
    {
      'question': 'ما الآثار الجانبية للمورفين التي يجب أن يراقبها المسعف الحربي؟',
      'answer': '1. التثبيط التنفسي (أخطرها): يراقب المسعف معدل التنفس، فإذا قل عن 10 أنفاس/دقيقة، يوقف المورفين ويعطي النالوكسون. 2. هبوط الضغط (توسع الأوردة): يمنع إعطاؤه إذا كان الضغط الانقباضي < 90 مم زئبق. 3. الغثيان والتقيؤ: يمكن إعطاء مضاد قيء (أوندانسيترون) معه. 4. الإمساك. 5. تضيق الحدقة (حدقة دبوسية).'
