    },
    {
      'question': 'ما مميزات الباراسيتامول (Paracetamol) كمخفف ألم في الميدان؟',
      'answer': 'مميزاته: 1. آمن على المعدة (لا يسبب قرحة). 2. لا يؤثر على تخثر الدم (آمن في الحمى النزفية مثل الضنك). 3. متوفر فموياً ووريدياً وتحاميل. 4. خافض حرارة فعال. عيوبه: 1. ضعيف في الآلام الشديدة. 2. سام للكبد في الجرعة الزائدة (أكثر من 4 غرام/يوم للبالغين). لا تعطه لمن يشرب الكحول أو يعاني من مرض كبدي.'
    },
    {
      'question': 'ما آلية عمل مضادات الالتهاب غير الستيرويدية (NSAIDs)؟',
      'answer': 'تثبط إنزيمات الأكسدة الحلقية (Cyclooxygenase - COX) التي تنتج البروستاغلاندينات المسؤولة عن الألم والالتهاب والحرارة. COX-1 موجود في المعدة والكلى والصفائح، وCOX-2 يظهر في الالتهاب. تثبيط COX-1 يسبب الآثار الجانبية (قرحة المعدة، نزيف، تأثير كلوي).'
    },
    {
      'question': 'ما أشهر مضادات الالتهاب غير الستيرويدية المستخدمة في الإسعاف الحربي؟',
      'answer': '1. الإيبوبروفين (Ibuprofen): فموي، 400-600 ملغ كل 6-8 ساعات. 2. الديكلوفيناك (Diclofenac): فموي أو حقن، 50-75 ملغ كل 12 ساعة. 3. الكيتورولاك (Ketorolac): حقن قوية، 15-30 ملغ كل 6 ساعات (أقصى 5 أيام). يستخدم في آلام المغص الكلوي. 4. الميلوكسيكام (Meloxicam): مثبط COX-2 انتقائي، أقل تأثيراً على المعدة.'
    },
    {
      'question': 'لماذا تمنع مضادات الالتهاب غير الستيرويدية في حالات النزيف أو حمى الضنك؟',
      'answer': 'لأنها تمنع تجمع الصفائح الدموية (تأثير مضاد للتخثر) وتزيد من خطر النزيف. في حمى الضنك، الصفائح منخفضة أصلاً، فإعطاء الأسبرين أو الإيبوبروفين أو الديكلوفيناك قد يسبب نزيفاً قاتلاً. لذلك الباراسيتامول هو الخيار الآمن الوحيد لخفض الحرارة في حمى الضنك.'
    },
    {
      'question': 'ما استخدام الكيتورولاك (Ketorolac) في الميدان وما محاذيره؟',
      'answer': 'الكيتورولاك مسكن قوي غير أفيوني، يعطى حقناً، يستخدم لتسكين الآلام المتوسطة إلى الشديدة (مثل المغص الكلوي، آلام العظام) عندما نريد تجنب الآثار الجانبية للأفيونات. محاذيره: يسبب قرحة ونزيف معدي، يضر الكلى خاصة في الجفاف أو الصدمة، يمنع استخدامه لأكثر من 5 أيام، ويمنع في الحمل والرضاعة.'
    },
    {
      'question': 'كيف تختار بين إعطاء الأفيون (مثل المورفين) ومضاد الالتهاب غير الستيرويدي لمصاب بكسر في الفخذ؟',
      'answer': 'القاعدة: تقييم حالة المصاب. إذا كان الألم شديداً جداً، والمصاب في صدمة، فالكيتامين (أو المورفين بحذر إذا كان الضغط مستقراً) هو الخيار الأفضل لتسكين الألم وتثبيت الكسر. إذا كان الألم متوسطاً والمصاب مستقراً، يمكن استخدام الكيتورولاك (حقنة) مع مراعاة عدم وجود نزيف نشط أو قرحة معدية. الباراسيتامول وحده غير كافٍ لكسر الفخذ.'
    },

    // ========== 131-150: المضادات الحيوية الأساسية ==========
    {
      'question': 'ما مبادئ استخدام المضادات الحيوية في البيئة العسكرية؟',
      'answer': '1. إعطاؤها مبكراً: خلال 3 ساعات من الإصابة في الجروح الملوثة. 2. اختيار مضاد واسع الطيف يغطي الجراثيم المتوقعة (موجبة وسالبة الغرام). 3. الجرعة الكافية من البداية. 4. الطريق الوريدي أو العضلي (وليس الفموي) في الإصابات الشديدة. 5. مراقبة علامات الحساسية. 6. إكمال مدة العلاج (5-7 أيام). 7. في الرعاية المطولة (PFC)، إذا تعذر الإخلاء لأكثر من 24 ساعة، يجب الاستمرار بالمضاد الحيوي.'
    },
    {
      'question': 'ما آلية عمل البنسلينات (مثل أموكسيسيلين)؟',
      'answer': 'البنسلينات ترتبط ببروتينات ربط البنسلين (PBPs) في جدار الخلية البكتيرية، فتمنع تكوين الببتيدوغليكان (المكون الأساسي للجدار)، مما يضعف الجدار وينفجر الخلية البكتيرية وتموت. هي مضادات قاتلة للبكتيريا (Bactericidal). فعالة بشكل أساسي ضد البكتيريا موجبة الغرام وبعض سالبة الغرام.'
    },
    {
      'question': 'ما الفرق بين الأموكسيسيلين العادي والأموكسيسيلين/كلافولانيت (Co-amoxiclav)؟',
      'answer': 'الأموكسيسيلين العادي تتكسر بواسطة إنزيم البيتا-لاكتاماز الذي تفرزه بعض البكتيريا المقاومة. أما الكو-أموكسيكلاف فيحتوي على الأموكسيسيلين + حمض الكلافولانيك (Clavulanic Acid) الذي يثبط إنزيم البيتا-لاكتاماز، فيحمي الأموكسيسيلين من التكسر ويوسع طيفه ليشمل بكتيريا مقاومة.'
    },
    {
      'question': 'ما دواعي استخدام سيفترياكسون (Ceftriaxone) في الميدان العسكري؟',
