    },
    {
      'question': 'ما هو الهيتاستارش (Hextend) ولماذا يُستخدم في إنعاش الصدمة النزفية الميدانية؟',
      'answer': 'هيتاستارش (Hextend) محلول غرواني يحتوي على جزيئات نشاء كبيرة تبقى داخل الأوعية الدموية لساعات، مما يحافظ على ضغط الدم بكمية أقل من البلورانيات. يستخدم في الميدان عندما لا يتوفر الدم أو عندما يحتاج المسعف لرفع الضغط سريعاً (Hypotensive Resuscitation) دون حمل كميات كبيرة من السوائل. لكن لا يعطى أكثر من 1 لتر لأنه قد يسبب اعتلال تخثر.'
