      'answer': 'متساوية التوتر (Isotonic): مثل الملح العادي 0.9% ورينغر لاكتات، لها نفس تركيز أملاح الدم، تبقى في الحيز خارج الخلوي. منخفضة التوتر (Hypotonic): مثل محلول سكري 5% (دكستروز)، تدخل الخلايا وتسبب تورمها، لا تستخدم في الصدمة. مرتفعة التوتر (Hypertonic): مثل ملح 3%، تسحب السوائل من الخلايا للأوعية، تستخدم في إصابات الرأس لسحب الماء من الدماغ المتورم.'
    },

    // ========== 176-185: أدوية التخثر والنزيف ==========
    {
      'question': 'ما آلية عمل حمض الترانيكساميك (TXA) وكيف يوقف النزيف؟',
      'answer': 'حمض الترانيكساميك (Tranexamic Acid) يثبط انحلال الفبرين (الجلطة). يرتبط بالبلازمينوجين ويمنع تحوله إلى بلازمين (الإنزيم الذي يذيب الجلطة). هكذا يحمي الجلطات المتكونة طبيعياً من التكسر، مما يقلل النزيف. لا يسبب تخثراً جديداً، بل يحافظ على الجلطات الموجودة. وهو دواء آمن وفعال إذا أعطي خلال 3 ساعات من الإصابة.'
    },
    {
      'question': 'ما جرعة TXA في الإصابات الحربية وكيف يعطى؟',
      'answer': 'الجرعة: 1 غرام (أمبولة 10 مل تحوي 1000 ملغ) تعطى وريدياً ببطء خلال 10 دقائق، في أسرع وقت بعد الإصابة (ويفضل خلال ساعة). إذا تأخر الإخلاء لأكثر من 3 ساعات، لا يعطى TXA (حسب بعض البروتوكولات) لأن الفائدة تقل وتظهر مضاعفات. يمكن تكرار الجرعة بعد 8 ساعات إذا استمر النزيف.'
