    {
      'question': 'ما هي التفاعلات الدوائية الخطيرة التي يجب أن ينتبه لها المسعف الحربي؟',
      'answer': '1. المورفين + النالوكسون (ترياق). 2. الأدرينالين + حاصرات بيتا (تأثير عكسي خطير). 3. الأسبرين + الوارفارين (نزيف قاتل). 4. السيبروفلوكساسين + مضادات الحموضة (تقلل الامتصاص). 5. المورفين + البنزوديازيبينات (مثل الديازيبام): كلاهما يثبط التنفس، فيكون التأثير متضاعفاً وخطيراً.'
    },
    {
      'question': 'ما الذي يفعله المسعف عند الشك في حدوث تفاعل دوائي تحسسي (حساسية) بعد إعطاء مضاد حيوي؟',
      'answer': 'الخطوة 1: أوقف الدواء فوراً. الخطوة 2: قيم شدة التفاعل (طفح جلدي بسيط أم صدمة تحسسية كاملة). الخطوة 3: إذا كان تفاعلاً خفيفاً (طفح، حكة): أعطِ مضاد هستامين (ديفينهيدرامين). الخطوة 4: إذا كان تفاعلاً شديداً (زلة تنفسية، هبوط ضغط، تورم حنجرة): أعطِ الأدرينالين 0.3-0.5 ملغ عضلياً فوراً، ثم هيدروكورتيزون وريدياً، وأكسجين، وافتح خطاً وريدياً، وأخلِ المصاب فوراً.'
    },

