      'question': 'كيف تضبط سرعة التنقيط الوريدي (IV Drip Rate) يدوياً في الميدان؟',
      'answer': 'القاعدة: عدد القطرات في الدقيقة = (حجم المحلول بالمل × معامل التنقيط) ÷ (الزمن بالساعات × 60). معامل التنقيط القياسي: 20 قطرة/مل. مثال: إذا أردت إعطاء 1000 مل من محلول الملح على مدى 8 ساعات: عدد القطرات = (1000 × 20) ÷ (8 × 60) = 20000 ÷ 480 = 42 قطرة/دقيقة تقريباً. تضبط السرعة يدوياً بعد القطرات بالعد.'
    },
