      'question': 'ما استخدام الواقع المعزز (AR) في التدريب على الحقن؟',
      'answer': 'يستخدم الواقع المعزز (AR) في تدريب المسعفين على الحقن: يرتدي الطالب نظارة AR أو يستخدم جهازاً لوحياً، فتظهر له علامات افتراضية على جسم الزميل أو النموذج تحدد بالضبط مواقع الحقن الصحيحة (مثل موقع العضلة الفخذية الوحشية، أو موقع الوريد)، مع إرشادات عن الزاوية الصحيحة للإبرة وعمق الإدخال، مما يقلل الأخطاء في التدريب.'
    },

    // ========== 201-215: السلامة الدوائية ومكافحة الأخطاء ==========
    {
      'question': 'ما مفهوم "السلامة الدوائية" (Medication Safety) في الإسعاف الحربي؟',
      'answer': 'السلامة الدوائية هي مجموعة الإجراءات التي تهدف إلى منع الأخطاء الدوائية التي قد تضر المصاب. وتشمل: 1. التحقق من الدواء والجرعة. 2. معرفة التفاعلات الدوائية. 3. التحقق من تاريخ الصلاحية. 4. حفظ الأدوية في ظروف مناسبة (حرارة، رطوبة، ضوء). 5. وضع بطاقات تعريف واضحة على كل حقنة محضرة. 6. توثيق الأدوية المعطاة فوراً.'
    },
    {
      'question': 'كيف تحفظ الأدوية في الميدان للحفاظ على فعاليتها؟',
      'answer': '1. الأدوية التي تحتاج تبريداً (مثل الأنسولين، بعض اللقاحات، TXA بعد الفتح): توضع في حافظات تبريد مع أكياس ثلج. 2. الأدوية الحساسة للضوء (مثل النيتروغليسرين، بعض المضادات الحيوية): تحفظ في عبوات معتمة. 3. معظم الأدوية: تحفظ في درجة حرارة الغرفة (15-25 درجة مئوية) بعيداً عن أشعة الشمس المباشرة. 4. الأمبولات الزجاجية: في علبها الأصلية لمنع الكسر. 5. توثيق تاريخ فتح القوارير متعددة الجرعات.'
    },
