    // ========== 216-230: التقييم والاختبارات ==========
    {
      'question': 'ما هو اختبار OSCE العملي في مقرر علم الأدوية؟',
      'answer': 'اختبار OSCE (الاختبار السريري العملي المنظم) في علم الأدوية يتكون من محطات تقييمية: محطة حساب جرعة (تعطى حالة وتطلب منك حساب الجرعة)، محطة تحضير حقنة (تحضر حقنة أدرينالين مثلاً)، محطة إعطاء حقنة عضلية على نموذج، محطة تحضير محلول وريدي وضبط سرعة التسريب، محطة التعرف على دواء من عبوته، ومحطة سيناريو متكامل (تعالج حالة صدمة تحسسية أو نزفية).'
