    // ========== 81-100: مبدأ الولاية ==========
    {
      'question': 'ما هو "مبدأ الولاية" كما يعرفه مقرر CQ-102-M؟',
      'answer': 'الولاية هي رابطة إيمانية وسياسية تعني التولي لله ورسوله وأهل البيت. تبدأ من ولاية الله، ثم رسوله، ثم الإمام علي والأئمة من ذريته. قال تعالى: ﴿إِنَّمَا وَلِيكُمُ اللَّهُ وَرَسُولُهُ وَالَّذِينَ آمَنُوا﴾ (المائدة: 55).'
    },
