      'answer': 'A1: يصف تركيب جسم الإنسان من مستوى الخلية إلى مستوى الجهاز، مع التركيز على المعالم التشريحية المستخدمة في الإجراءات الإسعافية الميدانية. A2: يشرح وظائف الأعضاء الرئيسية والآليات الفسيولوجية التي تحافظ على استتباب الجسم، وتأثير الإصابات القتالية والصدمات عليها. A3: يسرد المصطلحات التشريحية الأساسية (الأوضاع، المستويات، الاتجاهات) وتجاويف الجسم، مستخدماً المصطلحات الطبية العسكرية المعتمدة. A4: يحدد المعالم التشريحية السطحية والعميقة اللازمة لإجراءات: التنبيب الرغامي، الفغر الدرقي الطارئ، بزل الصدر بالإبرة، إدخال أنبوب الصدر، تركيب القساطر الوريدية المركزية والمحيطية، والضغط على نقاط النزف الرئيسية.'
