    },
    {
      'question': 'ما مخرجات المهارات العامة (D1-D4) في مقرر التشريح والوظائف؟',
      'answer': 'D1: يعمل ضمن فريق طبي عسكري لإعداد تقارير تربط التشريح بالإجراء الإسعافي. D2: يستخدم مصادر التعلم الإلكترونية وقواعد البيانات الطبية العسكرية ومنصات الواقع الافتراضي. D3: يناقش قضايا ميدانية معاصرة (متلازمة الهرس، إصابات الانفجار) بلغة علمية دقيقة. D4: يستشعر عظمة الخالق في دقة تركيب جسم الإنسان، ويتعامل مع المصابين برحمة ورفق.'
    },

