      'answer': 'القسطرة البولية (Foley Catheter) هي أنبوب يدخل عبر الإحليل إلى المثانة لتصريف البول. تتعلم تركيبها في NURS 201-M. دواعيها: احتباس بولي، مراقبة الصادر في الصدمة، إصابة حوض، قبل الإخلاء الجوي الطويل. يجب الالتزام بالتعقيم الصارم.'
    },
    {
      'question': 'كيف تركب قسطرة بولية لذكر في الميدان؟',
