      'question': 'ما الفرق بين تركيب القسطرة للذكر والأنثى؟',
      'answer': 'في الذكر: الإحليل أطول (20-25 سم)، تمسك القضيب عمودياً، تقاوم المقاومة عند البروستاتا. في الأنثى: الإحليل أقصر (3-5 سم)، تحتاج لتحديد فتحة الإحليل بدقة (بين البظر والمهبل). في كليهما: التعقيم الصارم هو الأساس.'
    },
    {
      'question': 'NG Tube',
      'answer': 'الأنبوب الأنفي المعدي (Nasogastric Tube) هو أنبوب يدخل عبر الأنف إلى المعدة. تتعلمه في NURS 201-M. دواعيه: 1. تخفيف ضغط المعدة (في الانسداد المعوي). 2. إعطاء التغذية والأدوية. 3. غسل المعدة (في التسمم). التأكد من الموضع: اسحب محتويات المعدة بحقنة وافحص pH (حامضي).'
