    },
    {
      'question': 'سلفاديازين الفضة',
      'answer': 'كريم سلفاديازين الفضة (Silver Sulfadiazine) هو مضاد حيوي موضعي للحروق. يقتل البكتيريا ويمنع العدوى في الحروق من الدرجة الثانية والثالثة. يوضع بطبقة سميكة (3-5 مم) على الحرق، ويغطى بضماد، ويغير مرتين يومياً. لا يستخدم على الوجه (قرب العينين) أو للحوامل.'
