      'answer': '1. وضعية فاولر (Fowler): استلقاء على الظهر، الرأس مرتفع 45-60 درجة. 2. وضعية شبه فاولر (Semi-Fowler): الرأس مرتفع 30 درجة. 3. الوضعية الجانبية (Lateral): على أحد الجانبين مع وسادة بين الركبتين. 4. الوضعية المائلة (Oblique): بزاوية 30 درجة على الظهر باستخدام وسائد. غيّر كل ساعتين.'
