      'answer': 'الفرز الطبي (Triage) هو عملية تصنيف المصابين حسب أولوية العلاج في الإصابات الجماعية (MASCAL). تتعلم في MFA-401-M نظام START (Simple Triage and Rapid Treatment) ونظام الألوان الأربعة: أحمر (فوري: يحتاج تدخلاً خلال دقائق)، أصفر (مؤجل: يمكنه الانتظار ساعة)، أخضر (بسيط: يمشي ويُصاب بجروح طفيفة)، أسود (متوقع الوفاة: إصابات لا تتوافق مع الحياة أو لا نبض بعد فتح مجرى الهواء).'
    },
    {
      'question': 'START',
      'answer': 'نظام START (Simple Triage and Rapid Treatment) هو طريقة لفرز المصابين بسرعة (أقل من 60 ثانية لكل مصاب). تفحص 3 أشياء فقط بالترتيب: 1. هل يمشي؟ (إذا نعم = أخضر). 2. هل يتنفس؟ (إذا لا، افتح مجرى الهواء: إذا بدأ يتنفس = أحمر، وإذا لا = أسود. إذا كان يتنفس >30 أو <10 = أحمر). 3. هل لديه نبض كعبري؟ (إذا لا = أحمر). 4. هل يستجيب للأوامر؟ (إذا لا = أحمر، وإذا نعم = أصفر).'
    },
    {
      'question': 'كيف تفرز 10 مصابين في حادث تفجير باستخدام نظام START؟',
      'answer': 'ابدأ بالجولة الأولى السريعة: اطلب من كل من يستطيع المشي أن يذهب لنقطة التجمع (هؤلاء أخضر). ثم ابدأ من أقرب مصاب: افحص التنفس (افتح مجرى الهواء إذا لا يتنفس)، النبض الكعبري، والوعي. صنف كل مصاب وضع بطاقة اللون المناسب (أحمر، أصفر، أخضر، أسود). لا تعالج أي مصاب حتى تنتهي من فرز الجميع. ثم ابدأ بعلاج الفئة الحمراء أولاً.'
    },
    {
      'question': 'ما الفرق بين نظام START ونظام SALT في الفرز الطبي؟',
      'answer': 'START أبسط وأسرع، يستخدم التنفس والنبض والوعي فقط. SALT (Sort, Assess, Life-saving interventions, Treatment/Transport) أكثر شمولاً: أولاً تفرز المصابين (Sort) إلى القادرين على المشي وغير القادرين، ثم تقيم (Assess)، ثم تجري تدخلات منقذة للحياة سريعة (Life-saving: عاصبة، فتح مجرى هواء، بزل صدر)، ثم تصنف للعلاج والنقل.'
    },
    {
      'question': 'ماذا تفعل إذا وجدت مصاباً لا يتنفس ولا نبض له في حادث إصابات جماعية؟',
      'answer': 'في الإصابات الجماعية (MASCAL) والموارد محدودة: إذا كان لا يتنفس، افتح مجرى الهواء بسرعة (ارفع الذقن أو ادفع الفك). إذا بدأ يتنفس، فهو أحمر. إذا لم يبدأ، صنفه أسود (متوقع الوفاة) وانتقل فوراً للمصاب التالي. لا تبدأ إنعاشاً قلبياً رئوياً في MASCAL لأنه يستهلك وقتك ومواردك لإنقاذ شخص واحد على حساب آخرين يمكن إنقاذهم.'
    },
    {
      'question': 'ما هي علامات الوفاة في الميدان (Injuries Incompatible with Life) التي تجعلك تصنف المصاب أسود؟',
      'answer': '1. إصابة دماغية مفتوحة مع فقدان مادة دماغية. 2. فصل كامل للجذع (Transection of torso). 3. تفحم كامل. 4. تحلل الجثة. 5. لا نبض ولا تنفس بعد فتح مجرى الهواء (في MASCAL). هذه الإصابات للأسف لا يمكن إنقاذها بالموارد المتاحة في الميدان.'
    },

    // ========== 101-130: إدارة مجرى الهواء المتقدم ==========
    {
      'question': 'ما الإجراءات المتقدمة لمجرى الهواء التي يتقنها الطالب في MFA-401-M؟',
      'answer': '1. التنبيب الرغامي (Endotracheal Intubation): إدخال أنبوب في القصبة الهوائية عبر الفم، وهو المعيار الذهبي لتأمين مجرى الهواء. 2. الفغر الحلقي الدرقي الجراحي (Surgical Cricothyroidotomy): فتح الغشاء الحلقي الدرقي جراحياً وإدخال أنبوب، يستخدم عندما يفشل التنبيب أو يكون مستحيلاً (إصابات الوجه الشديدة). 3. الأجهزة فوق المزمارية (i-gel، LMA): أسرع وأسهل من التنبيب، توضع فوق فتحة الحنجرة.'
    },
    {
