    },
    {
      'question': 'فغر حلقي',
      'answer': 'الفغر الحلقي الدرقي الجراحي (Surgical Cricothyroidotomy) هو إجراء طارئ تتعلمه في MFA-401-M، وهو البديل عندما يفشل التنبيب. تحدد الغشاء الحلقي الدرقي في الرقبة (الانخفاض بين تفاحة آدم والغضروف الحلقي)، تشق الجلد ثم الغشاء، وتدخل أنبوباً صغيراً للتهوية. تتدرب عليه على أقدام الخروف والمانيكانات.'
