    },
    {
      'question': 'متى تختار الفغر الحلقي الدرقي بدلاً من التنبيب؟',
      'answer': 'تختار الفغر الحلقي الدرقي عندما: 1. فشل التنبيب (لا تستطيع رؤية الأحبال الصوتية بسبب الدم أو التورم). 2. إصابة وجهية شديدة (كسور فك، أسنان مكسورة). 3. انسداد مجرى الهواء العلوي لا يمكن تجاوزه بالأنبوب. 4. المريض يحتاج لمجرى هواء فوراً ولا يوجد وقت لمحاولات التنبيب المتكررة.'
    },
    {
      'question': 'ما مضاعفات الفغر الحلقي الدرقي التي يجب أن ينتبه لها المسعف؟',
      'answer': '1. نزيف (من الأوعية الدرقية). 2. إصابة الغضروف الدرقي أو الحلقي. 3. وضع الأنبوب في غير مكانه (خارج القصبة الهوائية). 4. تضيق تحت المزمار (إذا بقي الأنبوب مدة طويلة). 5. بحة صوت دائمة. لكن تذكر: المضاعفات مقبولة مقابل إنقاذ حياة المصاب.'
    },

    // ========== 131-155: إصابات الصدر القتالية ==========
    {
      'question': 'كيف تعالج استرواح الصدر التوتري (Tension Pneumothorax) في الميدان؟',
      'answer': 'الخطوة 1: تعرف على العلامات بسرعة (غياب أصوات تنفس في جانب، انحراف رغامي، انتفاخ أوردة الرقبة، هبوط ضغط). الخطوة 2: حدد الموقع: المسافة الوربية الثانية على خط منتصف الترقوة (أو الوربية الخامسة على الخط الإبطي الأمامي). الخطوة 3: طهر المنطقة إن أمكن. الخطوة 4: أدخل إبرة قياس 14 (بطول 3.25 بوصة) فوق الحافة العلوية للضلع الثالث (أو السادس) عمودياً. الخطوة 5: اسمع خروج الهواء وتراجع الأعراض.'
    },
    {
      'question': 'بزل صدر',
      'answer': 'بزل الصدر بالإبرة (Needle Decompression) هو إجراء طارئ منقذ للحياة تتعلمه في MFA-401-M. تستخدمه لعلاج استرواح الصدر التوتري. تدخل إبرة كبيرة في الصدر لتحرير الهواء المحبوس. المواقع: إما المسافة الوربية الثانية في منتصف الترقوة، أو المسافة الوربية الخامسة على الخط الإبطي الأمامي (وهو المفضل حديثاً لضمان وصول الإبرة للتجويف الجنبي).'
    },
    {
      'question': 'متى تحتاج لإدخال أنبوب صدري (Chest Tube) بدلاً من بزل الصدر بالإبرة؟',
      'answer': 'البزل بالإبرة هو حل مؤقت. أنبوب الصدر هو الحل الدائم. تحتاجه عندما: 1. تعود أعراض التوتري بعد البزل. 2. هناك تدمي صدر (دم في التجويف الجنبي) يحتاج تصريفاً مستمراً. 3. لديك الوقت والموارد في مرحلة TFC أو TACEVAC. لكن في CUF، البزل فقط.'
    },
    {
      'question': 'كيف تغلق جرح الصدر النافذ (Sucking Chest Wound) بشكل صحيح؟',
      'answer': 'استخدم ضماداً صمامياً (Vented Chest Seal). إذا لم يتوفر، اصنع واحداً: ضع قطعة بلاستيك (غلاف ضمادة معقمة) على الجرح، وألصقها من 3 جهات فقط. اترك الجهة الرابعة مفتوحة لتسمح بخروج الهواء أثناء الزفير (صمام باتجاه واحد). لا تلصق الجهات الأربع كلها وإلا قد تسبب استرواحاً توترياً!'
    },
    {
      'question': 'ما هو تدمي الصدر (Hemothorax) وكيف تتعامل معه في الميدان؟',
      'answer': 'تدمي الصدر هو تجمع الدم في التجويف الجنبي. يحدث غالباً مع الاسترواح. العلامات: غياب أصوات التنفس + قرع أصم (ليس طبلياً) + علامات صدمة نزفية. إذا كان كتلياً (Massive Hemothorax: أكثر من 1500 مل)، يحتاج أنبوباً صدرياً لتصريف الدم وإعادة تمدد الرئة، ونقلاً عاجلاً للجراحة.'
    },

    // ========== 156-180: السيطرة على النزيف والدوران ==========
    {
      'question': 'Tourniquet',
      'answer': 'العاصبة (Tourniquet) هي أداة تضغط على الطرف لوقف النزيف الشرياني. في MFA-401-M تتعلم أنواعها (CAT، SOF-T) وكيفية تركيبها بشكل صحيح. القواعد: 1. في CUF، ركبها فوق الملابس في أعلى الطرف. 2. في TFC، اكشف الجرح، وإذا لم يكن هناك بتر كامل، حاول تحويلها لضمادة مرقئة بعد ساعتين إذا كانت الحالة مستقرة. 3. دوّن وقت التركيب على جبين المصاب أو على العاصبة نفسها.'
    },
    {
      'question': 'Combat Gauze',
