    },
    {
      'question': 'Junctional Tourniquet',
      'answer': 'بالونات السد الوصلي (Junctional Tourniquets) هي أجهزة تضغط على المناطق التي تلتقي فيها الأطراف بالجذع (الفخذ مع الحوض، الإبط مع الكتف) حيث لا يمكن استخدام العاصبة التقليدية. أمثلتها: AAJT، CRoC، SJT. تتعلم عليها في MFA-401-M لأن النزيف الوصلي هو السبب الأول للوفاة التي يمكن منعها في القتال.'
    },
    {
      'question': 'كيف تختار بين العاصبة والضمادة المرقئة والضغط المباشر لنزيف معين؟',
      'answer': 'العاصبة: لأي نزيف شرياني صاعق في الأطراف، أو بتر كامل/جزئي، أو عندما تكون تحت النيران ولا وقت للفحص. الضمادة المرقئة: للنزيف المتوسط إلى الشديد في المناطق التي لا تصلح لها العاصبة (الرقبة، الإبط، أصل الفخذ). الضغط المباشر: للنزيف الوريدي الخفيف إلى المتوسط في أي مكان.'
    },
    {
      'question': 'كيف تركب قسطرة داخل العظم (IO) باستخدام جهاز EZ-IO في الميدان؟',
      'answer': 'الخطوة 1: حدد الموقع (رأس القصبة تحت الركبة هو الأسهل، أو رأس العضد). الخطوة 2: طهر الجلد. الخطوة 3: ثبت الجهاز عمودياً على العظم، واضغط الزناد. الخطوة 4: ستدخل الإبرة تلقائياً. الخطوة 5: انزع المحرك، ثبت القسطرة، اسحب النخاع للتأكد (أو اغسل بالمحلول الملحي). الخطوة 6: علق المحلول وابدأ التسريب. استخدمه عندما تفشل في إيجاد وريد خلال 90 ثانية أو في حالة الصدمة الشديدة.'
    },

    // ========== 181-200: إنعاش الصدمة النزفية ونقل الدم ==========
    {
      'question': 'TXA',
      'answer': 'حمض الترانيكساميك (TXA) هو دواء يمنع انحلال الجلطات (الفيبرينوليسيس). في MFA-401-M تتعلم أن تعطيه لكل مصاب بصدمة نزفية شديدة. الجرعة: 1 غرام وريدياً ببطء خلال 10 دقائق، خلال أول 3 ساعات من الإصابة (الأفضل خلال ساعة واحدة). لا تعطه بعد 3 ساعات لأنه قد يزيد الضرر.'
    },
    {
      'question': 'ما هو الإنعاش المتوازن (Balanced Resuscitation) الذي تدرسه في MFA-401-M؟',
      'answer': 'الإنعاش المتوازن هو إعطاء مكونات الدم بنسبة متساوية (1:1:1): كريات دم حمراء : بلازما : صفائح دموية. هذا يحاكي الدم الكامل. في الميدان، إذا لم تتوفر المكونات المنفصلة، نستخدم "الدم الكامل الطازج" (Fresh Whole Blood) من متبرع متوافق. الهدف: تعويض ما فقده المصاب بالضبط، وليس فقط سوائل.'
    },
    {
      'question': 'كيف تنقل دماً كاملاً طازجاً (Fresh Whole Blood) في الميدان؟',
      'answer': 'الخطوة 1: تأكد من الفصيلة: استخدم شريط فحص سريع (Eldon Card) للمتبرع والمصاب. الخطوة 2: اسحب الدم من المتبرع (450 مل) في كيس جمع مع مضاد تخثر. الخطوة 3: علق الكيس وابدأ التسريب ببطء (راقب العلامات الحيوية). الخطوة 4: الأفضل إعطاؤه دافئاً (Warm Fresh Whole Blood) لأنه يحافظ على وظائف الصفائح وعوامل التخثر. الخطوة 5: راقب علامات تفاعل نقل الدم (حكة، طفح، صعوبة تنفس).'
    },
    {
      'question': 'ما هو مبدأ "الإنعاش منخفض الضغط" (Hypotensive Resuscitation) ومتى تطبقه؟',
      'answer': 'في الصدمة النزفية غير المسيطر عليها (خاصة النزيف الداخلي في البطن أو الحوض)، لا تحاول رفع الضغط للمستوى الطبيعي (120/80). تهدف فقط لضغط انقباضي 80-90 مم زئبق (أو وجود نبض كعبري). لماذا؟ لأن الضغط العالي قد "يفرقع" الجلطات الهشة المتكونة في مواقع النزيف ويزيد النزيف سوءاً. استخدم كميات قليلة من السوائل (250-500 مل من الدم أو Hextend دفعة واحدة).'
    },

    // ========== 201-215: تثبيت الكسور وإصابات العمود الفقري ==========
    {
      'question': 'كيف تركب جبيرة السحب (Traction Splint) لكسر الفخذ في الميدان؟',
      'answer': 'الخطوة 1: قس طول الجبيرة على الساق السليمة. الخطوة 2: ضع الجبيرة تحت الساق المصابة، وثبت الحلقة الإسكية عند أصل الفخذ (تحت الأرداف). الخطوة 3: ثبت الأشرطة حول الفخذ والقصبة. الخطوة 4: اربط الشريط المطاطي حول الكاحل. الخطوة 5: مد الجبيرة ببطء حتى تشعر بمقاومة، ثم مد أكثر قليلاً (حوالي 10% من طول الطرف). الخطوة 6: ثبت كل شيء. الجبيرة تقلل الألم، تمنع المزيد من النزيف، وتقلل خطر الصمة الدهنية.'
    },
    {
      'question': 'Pelvic Binder',
      'answer': 'رباط الحوض (Pelvic Binder) هو حزام يلف حول الحوض لتثبيت كسور الحوض غير المستقرة. في MFA-401-M تتعلم تركيبه عند الاشتباه بكسر حوضي (ألم حوضي، عدم استقرار باللمس). ضعه على مستوى المدورين الكبيرين (أعلى عظم الفخذ)، وليس على البطن. شده بقوة لإغلاق حلقة الحوض وتقليل حجم التجويف الحوضي، مما يوقف النزيف بالضغط.'
    },
