      'question': 'كيف تثبت العمود الفقري لمصاب مشتبه بإصابة نخاعية؟',
      'answer': 'الخطوة 1: ثبّت الرأس يدوياً في الوضع المحايد (لا تثنِ ولا تدور). الخطوة 2: ضع طوق العنق الصلب. الخطوة 3: ضع لوح العمود الفقري الطويل بجانب المصاب. الخطوة 4: بمساعدة 3-4 أشخاص، ارفع المصاب كقطعة واحدة (Log Roll) وانقله للوح. الخطوة 5: ثبت الجذع والحوض والأطراف على اللوح بالأشرطة. الخطوة 6: ثبت الرأس أخيراً بكتل رأسية وشريط.'
    },

    // ========== 216-230: الحروق القتالية وإدارة الألم ==========
    {
      'question': 'كيف تحسب مساحة الحروق باستخدام قاعدة التسعات (Rule of Nines)؟',
      'answer': 'تقسم الجسم لمناطق كل منها 9% أو مضاعفاتها: الرأس والرقبة = 9%، كل طرف علوي = 9%، كل طرف سفلي = 18% (أمامي 9% + خلفي 9%)، الصدر = 9%، البطن = 9%، الظهر العلوي = 9%، الظهر السفلي = 9%، الأعضاء التناسلية = 1%. مجموعها 100%. استخدم هذه القاعدة لتقدير كمية السوائل التي يحتاجها المصاب بالحروق.'
